@dbTable(Q1,SELECT REG.F1101,REG.F1063,REG.F1079,REG.F64,F65=CASE WHEN HDR.F1068='REFUND' THEN -REG.F65 ELSE REG.F65 END 
FROM SAL_REG REG JOIN SAL_HDR HDR ON HDR.F1032=REG.F1032
WHERE HDR.F1032=0@dbHot(SAL_HDR,F1032,#) and HDR.F1068 IN ('SALE','REFUND') AND REG.F1069<>'1' AND REG.F1063 BETWEEN 100 and 200)

	@dbRow(Q1,F1101,#)
	@dbRow(Q1,F1063,#)
	@dbRow(Q1,F1079)
	@dbRow(Q1,F64,#)
	@dbRow(Q1,F65,#)
